WITH
INPUT_SCOPE AS (
  SELECT
    CASE WHEN '{{scopeMode}}' IN ('TEAM', 'SELLER', 'GLOBAL') THEN '{{scopeMode}}' ELSE 'ME' END AS SCOPE_MODE,
    CASE WHEN '{{scopeUserId}}' REGEXP '^[0-9]+$' THEN CAST('{{scopeUserId}}' AS UNSIGNED) ELSE NULL END AS SCOPE_USER_ID,
    CASE WHEN '{{scopeCodRca}}' REGEXP '^[0-9]+$' THEN CAST('{{scopeCodRca}}' AS UNSIGNED) ELSE NULL END AS SCOPE_COD_RCA,
    CASE WHEN '{{scopeCodFilial}}' = '' OR LOCATE('{', '{{scopeCodFilial}}') > 0 THEN NULL ELSE TRIM('{{scopeCodFilial}}') END AS SCOPE_CODFILIAL,
    CASE WHEN '{{scopeCodepto}}' = '' OR LOCATE('{', '{{scopeCodepto}}') > 0 THEN NULL ELSE TRIM('{{scopeCodepto}}') END AS SCOPE_CODEPTO,
    CASE WHEN '{{scopeIdSecao}}' = '' OR LOCATE('{', '{{scopeIdSecao}}') > 0 THEN NULL ELSE TRIM('{{scopeIdSecao}}') END AS SCOPE_ID_SECAO,
    CASE WHEN '{{scopeCodSupervisor}}' REGEXP '^[0-9]+$' THEN CAST('{{scopeCodSupervisor}}' AS UNSIGNED) ELSE NULL END AS SCOPE_COD_SUPERVISOR
),
TARGET_USERS AS (
  SELECT :VAR_USER AS USER_ID
  FROM INPUT_SCOPE I
  WHERE I.SCOPE_MODE = 'ME'
  UNION
  SELECT F.ID AS USER_ID
  FROM INPUT_SCOPE I
  JOIN FUNCIONARIOS F ON F.ID_SUBSTITUTO = :VAR_USER
  WHERE I.SCOPE_MODE = 'ME'
  UNION
  SELECT VR_DONO.USER_ID AS USER_ID
  FROM INPUT_SCOPE I
  JOIN VENDEDOR_RCA VR_SUB ON VR_SUB.USER_ID = :VAR_USER
  JOIN FERIAS_VENDEDOR FV ON FV.COD_RCA_SUBSTITUTO = VR_SUB.COD_RCA
  JOIN VENDEDOR_RCA VR_DONO ON VR_DONO.COD_RCA = FV.COD_RCA
  WHERE I.SCOPE_MODE = 'ME'
    AND COALESCE(FV.ATIVO, TRUE) = TRUE
    AND CURRENT_DATE BETWEEN FV.DT_INICIO AND FV.DT_FIM
  UNION
  SELECT DISTINCT BV.VENDEDOR_ID AS USER_ID
  FROM INPUT_SCOPE I
  JOIN COORDENADORES C ON C.USER_ID = :VAR_USER AND COALESCE(C.ATIVO, TRUE) = TRUE
  JOIN COORDENADORES_BU CB ON CB.COD_SUPERVISOR = C.COD_SUPERVISOR
  JOIN BU_VENDEDOR BV
    ON TRIM(COALESCE(CAST(BV.CODFILIAL AS CHAR), '')) = CAST(CB.CODFILIAL AS CHAR)
   AND TRIM(CAST(BV.BU_CODIGO AS CHAR)) = CAST(CB.CODEPTO AS CHAR)
  WHERE I.SCOPE_MODE = 'TEAM'
    AND COALESCE(BV.ATIVO, TRUE) = TRUE
    AND NOT EXISTS (
      SELECT 1
      FROM COORDENADORES C_COORD_ALVO
      WHERE C_COORD_ALVO.USER_ID = BV.VENDEDOR_ID
        AND COALESCE(C_COORD_ALVO.ATIVO, TRUE) = TRUE
        AND C_COORD_ALVO.USER_ID <> :VAR_USER
    )
    AND (I.SCOPE_CODFILIAL IS NULL OR TRIM(COALESCE(CAST(BV.CODFILIAL AS CHAR), '')) = I.SCOPE_CODFILIAL)
    AND (I.SCOPE_CODEPTO IS NULL OR TRIM(CAST(BV.BU_CODIGO AS CHAR)) = I.SCOPE_CODEPTO)
    AND (
      I.SCOPE_ID_SECAO IS NULL
      OR TRIM(CAST(BV.ID_SECAO AS CHAR)) = I.SCOPE_ID_SECAO
      OR LPAD(TRIM(CAST(BV.ID_SECAO AS CHAR)), 2, '0') = I.SCOPE_ID_SECAO
    )
  UNION
  SELECT DISTINCT BV.VENDEDOR_ID AS USER_ID
  FROM INPUT_SCOPE I
  JOIN INT_USER U ON U.ID = :VAR_USER
  LEFT JOIN USUARIO_CARGO UC ON UC.USER_ID = U.ID
  JOIN BU_VENDEDOR BV ON COALESCE(BV.ATIVO, TRUE) = TRUE
  LEFT JOIN VENDEDOR_RCA VR ON VR.USER_ID = BV.VENDEDOR_ID
  WHERE I.SCOPE_MODE = 'SELLER'
    AND (BV.VENDEDOR_ID = I.SCOPE_USER_ID OR VR.COD_RCA = I.SCOPE_COD_RCA)
    AND (
      UPPER(COALESCE(UC.CARGO, '')) IN ('ADMIN', 'DIRETORIA')
      OR LOWER(COALESCE(U.DESCR, '')) = 'ti@benenutri.com'
      OR EXISTS (
        SELECT 1
        FROM COORDENADORES C
        JOIN COORDENADORES_BU CB ON CB.COD_SUPERVISOR = C.COD_SUPERVISOR
        WHERE C.USER_ID = :VAR_USER
          AND COALESCE(C.ATIVO, TRUE) = TRUE
          AND TRIM(COALESCE(CAST(BV.CODFILIAL AS CHAR), '')) = CAST(CB.CODFILIAL AS CHAR)
          AND TRIM(CAST(BV.BU_CODIGO AS CHAR)) = CAST(CB.CODEPTO AS CHAR)
      )
    )
    AND (I.SCOPE_CODFILIAL IS NULL OR TRIM(COALESCE(CAST(BV.CODFILIAL AS CHAR), '')) = I.SCOPE_CODFILIAL)
    AND (I.SCOPE_CODEPTO IS NULL OR TRIM(CAST(BV.BU_CODIGO AS CHAR)) = I.SCOPE_CODEPTO)
    AND (
      I.SCOPE_ID_SECAO IS NULL
      OR TRIM(CAST(BV.ID_SECAO AS CHAR)) = I.SCOPE_ID_SECAO
      OR LPAD(TRIM(CAST(BV.ID_SECAO AS CHAR)), 2, '0') = I.SCOPE_ID_SECAO
    )
  UNION
  SELECT DISTINCT BV.VENDEDOR_ID AS USER_ID
  FROM INPUT_SCOPE I
  JOIN INT_USER U ON U.ID = :VAR_USER
  LEFT JOIN USUARIO_CARGO UC ON UC.USER_ID = U.ID
  JOIN BU_VENDEDOR BV ON COALESCE(BV.ATIVO, TRUE) = TRUE
  WHERE I.SCOPE_MODE = 'GLOBAL'
    AND (
      UPPER(COALESCE(UC.CARGO, '')) IN ('ADMIN', 'DIRETORIA')
      OR LOWER(COALESCE(U.DESCR, '')) = 'ti@benenutri.com'
    )
    AND (
      I.SCOPE_COD_SUPERVISOR IS NULL
      OR EXISTS (
        SELECT 1
        FROM COORDENADORES C_GLOBAL_SELF
        WHERE C_GLOBAL_SELF.USER_ID = BV.VENDEDOR_ID
          AND COALESCE(C_GLOBAL_SELF.ATIVO, TRUE) = TRUE
          AND C_GLOBAL_SELF.COD_SUPERVISOR = I.SCOPE_COD_SUPERVISOR
      )
      OR (
        NOT EXISTS (
          SELECT 1
          FROM COORDENADORES C_GLOBAL_OTHER_COORD
          WHERE C_GLOBAL_OTHER_COORD.USER_ID = BV.VENDEDOR_ID
            AND COALESCE(C_GLOBAL_OTHER_COORD.ATIVO, TRUE) = TRUE
        )
        AND EXISTS (
          SELECT 1
          FROM COORDENADORES_BU CB_GLOBAL
          WHERE CB_GLOBAL.COD_SUPERVISOR = I.SCOPE_COD_SUPERVISOR
            AND TRIM(COALESCE(CAST(BV.CODFILIAL AS CHAR), '')) = CAST(CB_GLOBAL.CODFILIAL AS CHAR)
            AND TRIM(CAST(BV.BU_CODIGO AS CHAR)) = CAST(CB_GLOBAL.CODEPTO AS CHAR)
        )
      )
    )
    AND (I.SCOPE_CODFILIAL IS NULL OR TRIM(COALESCE(CAST(BV.CODFILIAL AS CHAR), '')) = I.SCOPE_CODFILIAL)
    AND (I.SCOPE_CODEPTO IS NULL OR TRIM(CAST(BV.BU_CODIGO AS CHAR)) = I.SCOPE_CODEPTO)
    AND (
      I.SCOPE_ID_SECAO IS NULL
      OR TRIM(CAST(BV.ID_SECAO AS CHAR)) = I.SCOPE_ID_SECAO
      OR LPAD(TRIM(CAST(BV.ID_SECAO AS CHAR)), 2, '0') = I.SCOPE_ID_SECAO
    )
),
-- CORRECAO 1: ESCOPO agora sai do TARGET_USERS (respeita scopeMode/scopeUserId/scopeCodSupervisor),
-- em vez de ficar preso ao usuario logado (:VAR_USER). Assim a diretoria consegue ver a
-- analise detalhada do vendedor/coordenador selecionado.
-- CORRECAO 2: o escopo de filial/depto/secao vem INTEIRO do BU_VENDEDOR (o vinculo de escopo real).
-- A EQUIPE_CLIENTE serve so para dizer que o cliente esta na carteira do vendedor (join so por
-- VENDEDOR_ID). Antes a seção era amarrada as colunas da EQUIPE_CLIENTE, o que derrubava seções
-- que o vendedor tem no BU_VENDEDOR mas nao constavam na EQUIPE_CLIENTE (ex.: seção 202).
ESCOPO AS (
  SELECT DISTINCT
    EC.ID_CLIENTE,
    BV.CODFILIAL,
    BV.BU_CODIGO AS CODEPTO,
    BV.ID_SECAO
  FROM EQUIPE_CLIENTE EC
  JOIN TARGET_USERS TU ON TU.USER_ID = EC.ID_VENDEDOR
  JOIN BU_VENDEDOR BV ON BV.VENDEDOR_ID = EC.ID_VENDEDOR
    AND COALESCE(BV.ATIVO, TRUE) = TRUE
    AND TRIM(COALESCE(CAST(BV.CODFILIAL AS CHAR), '')) <> ''
    AND TRIM(COALESCE(CAST(BV.BU_CODIGO AS CHAR), '')) <> ''
),
MOVIMENTOS_SEMANA AS (
  SELECT
    CAST(DATE_FORMAT(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), '%Y') AS UNSIGNED) AS ANO,
    MONTH(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))) AS MES,
    CASE WHEN GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)) = DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY) THEN 1 ELSE 2 + FLOOR(DATEDIFF(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), DATE_ADD(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), INTERVAL (CASE WHEN ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) = 0 THEN 7 ELSE ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) END) DAY)) / 7) END AS SEMANA_NUMERO,
    DATE_FORMAT(MIN(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))), '%Y-%m-%d') AS DATA_INICIO,
    DATE_FORMAT(MAX(LEAST(LAST_DAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')), DATE_ADD(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY), INTERVAL 6 DAY))), '%Y-%m-%d') AS DATA_FIM,
    COUNT(DISTINCT COALESCE(NULLIF(CAST(R.NUMPED AS CHAR), ''), CAST(R.NUMTRANSVENDA AS CHAR))) AS TOTAL_PEDIDOS,
    SUM(COALESCE(R.TOTAL, 0)) AS VALOR
  FROM PEDIDOS_SEMANAIS_SYNC_RAW R
  JOIN ESCOPO E ON E.ID_CLIENTE = R.CLIENTE_ID
    AND E.CODFILIAL = R.CODFILIAL
    AND E.CODEPTO = R.CODEPTO
    AND (
      E.ID_SECAO IS NULL
      OR E.ID_SECAO = R.ID_SECAO
    )
  WHERE R.ATIVO = TRUE
    AND R.STATUS_INGESTAO = 'ATIVO'
    AND CAST(R.DATA_SAIDA AS CHAR) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}'
    AND R.CLIENTE_ID = {{ID_CLIENTE}}
    AND CAST(DATE_FORMAT(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), '%Y') AS UNSIGNED) = CASE WHEN '{{ANO}}' = '' THEN CAST(DATE_FORMAT(GREATEST(DATE_SUB(CURRENT_DATE, INTERVAL (DAYOFMONTH(CURRENT_DATE) - 1) DAY), DATE_SUB(CURRENT_DATE, INTERVAL ((WEEKDAY(CURRENT_DATE) + 3) % 7) DAY)), '%Y') AS UNSIGNED) ELSE CAST('{{ANO}}' AS UNSIGNED) END
    AND ('{{MES}}' = '' OR MONTH(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))) = CAST('{{MES}}' AS UNSIGNED))
  GROUP BY CAST(DATE_FORMAT(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), '%Y') AS UNSIGNED), MONTH(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))), CASE WHEN GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)) = DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY) THEN 1 ELSE 2 + FLOOR(DATEDIFF(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), DATE_ADD(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), INTERVAL (CASE WHEN ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) = 0 THEN 7 ELSE ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(R.DATA_SAIDA AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) END) DAY)) / 7) END
  UNION ALL
  SELECT
    CAST(DATE_FORMAT(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), '%Y') AS UNSIGNED) AS ANO,
    MONTH(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))) AS MES,
    CASE WHEN GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)) = DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY) THEN 1 ELSE 2 + FLOOR(DATEDIFF(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), DATE_ADD(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), INTERVAL (CASE WHEN ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) = 0 THEN 7 ELSE ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) END) DAY)) / 7) END AS SEMANA_NUMERO,
    DATE_FORMAT(MIN(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))), '%Y-%m-%d') AS DATA_INICIO,
    DATE_FORMAT(MAX(LEAST(LAST_DAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')), DATE_ADD(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY), INTERVAL 6 DAY))), '%Y-%m-%d') AS DATA_FIM,
    0 AS TOTAL_PEDIDOS,
    -SUM(COALESCE(D.VALOR_DEVOLVIDO, 0)) AS VALOR
  FROM IMP_DEVOLUCOES_TOTVS D
  JOIN CLIENTES CD ON CD.WINTHOR_CODCLI = D.CODCLI
  JOIN ESCOPO E ON E.ID_CLIENTE = CD.ID
    AND E.CODFILIAL = TRIM(COALESCE(CAST(D.CODFILIAL AS CHAR), ''))
    AND E.CODEPTO = TRIM(CAST(D.CODEPTO AS CHAR))
    AND (
      E.ID_SECAO IS NULL
      OR E.ID_SECAO = CAST(D.CODSEC AS SIGNED)
      OR LPAD(TRIM(CAST(E.ID_SECAO AS CHAR)), 2, '0') = TRIM(CAST(D.CODSEC AS CHAR))
    )
  WHERE CAST(D.DATA_DEVOLUCAO AS CHAR) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}'
    AND CD.ID = {{ID_CLIENTE}}
    AND CAST(DATE_FORMAT(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), '%Y') AS UNSIGNED) = CASE WHEN '{{ANO}}' = '' THEN CAST(DATE_FORMAT(GREATEST(DATE_SUB(CURRENT_DATE, INTERVAL (DAYOFMONTH(CURRENT_DATE) - 1) DAY), DATE_SUB(CURRENT_DATE, INTERVAL ((WEEKDAY(CURRENT_DATE) + 3) % 7) DAY)), '%Y') AS UNSIGNED) ELSE CAST('{{ANO}}' AS UNSIGNED) END
    AND ('{{MES}}' = '' OR MONTH(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))) = CAST('{{MES}}' AS UNSIGNED))
  GROUP BY CAST(DATE_FORMAT(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), '%Y') AS UNSIGNED),
           MONTH(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY))),
           CASE WHEN GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)) = DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY) THEN 1 ELSE 2 + FLOOR(DATEDIFF(GREATEST(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL ((WEEKDAY(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) + 3) % 7) DAY)), DATE_ADD(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY), INTERVAL (CASE WHEN ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) = 0 THEN 7 ELSE ((4 - WEEKDAY(DATE_SUB(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d'), INTERVAL (DAYOFMONTH(STR_TO_DATE(LEFT(TRIM(CAST(D.DATA_DEVOLUCAO AS CHAR)), 10), '%Y-%m-%d')) - 1) DAY)) + 7) % 7) END) DAY)) / 7) END
)
SELECT
  M.ANO,
  M.MES,
  M.SEMANA_NUMERO,
  DATE_FORMAT(MIN(STR_TO_DATE(M.DATA_INICIO, '%Y-%m-%d')), '%Y-%m-%d') AS DATA_INICIO_SEMANA,
  DATE_FORMAT(MAX(STR_TO_DATE(M.DATA_FIM, '%Y-%m-%d')), '%Y-%m-%d') AS DATA_FIM_SEMANA,
  SUM(M.TOTAL_PEDIDOS) AS TOTAL_PEDIDOS,
  ROUND(SUM(M.VALOR), 2) AS VALOR_TOTAL_SEMANA
FROM MOVIMENTOS_SEMANA M
GROUP BY M.ANO, M.MES, M.SEMANA_NUMERO
ORDER BY M.ANO DESC, M.MES DESC, M.SEMANA_NUMERO DESC